_maybe_run_conda_init() {
    case $SHELL in
        # We call the module directly to avoid issues with spaces in shebang
        *zsh) "$PREFIX/bin/python" -m conda init zsh ;;
        *) "$PREFIX/bin/python" -m conda init ;;
